={
  "query": "query LabelBridgeFulfillmentOrders($id: ID!) { order(id: $id) { id name fulfillmentOrders(first: 5) { nodes { id status deliveryMethod { methodType } } } } }",
  "variables": { "id": "{{ $json.order_gid }}" }
}

parameters.jsCode:
// Comprueba la configuración y elige la primera fulfillment order ABIERTA
// (status OPEN) que necesite envío. Si existen fulfillment orders pero
// ninguna está abierta (pedido ya preparado, recogida en tienda, entrega
// local...) devolvemos 0 items y el workflow termina SIN comprar nada.

const ctx = $('Configuración').first().json;
const res = $input.first().json;

// Antes de comprar: el canal debe ser válido o la etiqueta no llegaría al PC.
if (!/^[a-z0-9-]+$/.test(String(ctx.canal ?? ''))) {
  throw new Error(`Canal inválido "${ctx.canal}" en "Configuración": usa solo minúsculas, números y guiones (el mismo canal que en la app).`);
}

if (Array.isArray(res.errors) && res.errors.length) {
  throw new Error('Shopify GraphQL (fulfillment orders): ' + JSON.stringify(res.errors));
}

const order = res.data?.order;
if (!order) {
  throw new Error(`No se pudo leer el pedido ${ctx.order_gid}. Revisa la credencial, el subdominio en "Configuración" y el scope read_orders.`);
}

const nodes = order.fulfillmentOrders?.nodes ?? [];
if (nodes.length === 0) {
  throw new Error(`El pedido ${ctx.order_name} no tiene fulfillment orders visibles para la app. ` +
    'Revisa el scope write_merchant_managed_fulfillment_orders (o reintenta la ejecución si el pedido se acaba de crear).');
}

// Métodos de entrega que no llevan etiqueta de transportista.
const SIN_ETIQUETA = ['PICK_UP', 'LOCAL', 'RETAIL', 'NONE'];
const fo = nodes.find((f) => f.status === 'OPEN' && !SIN_ETIQUETA.includes(f.deliveryMethod?.methodType));

if (!fo) {
  return [];   // nada que comprar
}

// shippingDatetime no puede estar en el pasado: usamos "ahora + 5 minutos".
const shippingDatetime = new Date(Date.now() + 5 * 60 * 1000).toISOString();

return [{
  json: {
    ...ctx,
    fulfillment_order_id: fo.id,
    shipping_datetime: shippingDatetime,
  },
}];

parameters.jsonBody:
={
  "query": "mutation LabelBridgeComprarEtiqueta($foId: ID!, $shippingDatetime: DateTime!) { shippingLabelPurchase(shippingLabelPurchase: { fulfillmentOrderId: $foId, shippingDatetime: $shippingDatetime }) { shippingLabelPurchaseResult { id status } userErrors { field code message } } }",
  "variables": { "foId": "{{ $json.fulfillment_order_id }}", "shippingDatetime": "{{ $json.shipping_datetime }}" }
}

parameters.jsCode:
// Revisa la respuesta de shippingLabelPurchase.
// - userErrors = validación síncrona (dirección, paquete, peso, aduanas, sin tarifas,
//   FedEx...). En ese caso Shopify NO compra nada y paramos con un error claro.
// - Si se aceptó, guardamos el id del ShippingLabelPurchaseResult para consultarlo.

const ctx = $('Elegir fulfillment order abierta').first().json;
const res = $input.first().json;

if (Array.isArray(res.errors) && res.errors.length) {
  throw new Error('Shopify GraphQL (shippingLabelPurchase): ' + JSON.stringify(res.errors));
}

const payload = res.data?.shippingLabelPurchase ?? {};
const userErrors = payload.userErrors ?? [];
if (userErrors.length) {
  const detalle = userErrors.map((e) => `${e.code ?? ''} ${e.message}`.trim()).join(' | ');
  throw new Error(`Shopify no aceptó la compra de la etiqueta (${ctx.order_name}): ${detalle}`);
}

const result = payload.shippingLabelPurchaseResult;
if (!result?.id) {
  throw new Error(`Shopify no devolvió shippingLabelPurchaseResult.id (${ctx.order_name}).`);
}

return [{ json: { ...ctx, result_id: result.id, status: result.status } }];

parameters.jsonBody:
={
  "query": "query LabelBridgeEstadoCompra($id: ID!) { node(id: $id) { ... on ShippingLabelPurchaseResult { status errors { code message } shippingLabels { id trackingInfo { number company url } shippingDocuments { documentType format url } } } } }",
  "variables": { "id": "{{ $json.result_id }}" }
}

parameters.jsCode:
// Decide el siguiente paso según el estado de la compra:
//   PURCHASED        → "imprimir"
//   PURCHASE_FAILED  → "fallo"
//   PENDING_PURCHASE → "esperar" (vuelve a "Esperar 5 s") hasta MAX_INTENTOS
const MAX_INTENTOS = 12;   // 12 consultas × 5 s ≈ 1 minuto

if (typeof $runIndex !== 'number') {
  throw new Error('No se pudo leer $runIndex: se detiene el sondeo por seguridad.');
}

const ctx = $('Preparar sondeo').first().json;
const res = $input.first().json;
const intento = $runIndex + 1;   // veces que se ha ejecutado este nodo en esta ejecución

// Un error GraphQL puntual (p. ej. límite de peticiones) no detiene el sondeo.
const errorDeConsulta = Array.isArray(res.errors) && res.errors.length > 0;
const resultado = errorDeConsulta ? {} : (res.data?.node ?? {});
const status = errorDeConsulta ? 'ERROR_CONSULTA' : (resultado.status ?? 'DESCONOCIDO');

let siguiente = 'esperar';
let mensaje = '';

if (status === 'PURCHASED') {
  siguiente = 'imprimir';
} else if (status === 'PURCHASE_FAILED') {
  siguiente = 'fallo';
  const detalle = (resultado.errors ?? []).map((e) => `${e.code}: ${e.message}`).join(' | ');
  mensaje = `La compra de la etiqueta falló (${ctx.order_name}): ${detalle || 'sin detalle'}`;
} else if (intento >= MAX_INTENTOS) {
  siguiente = 'fallo';
  mensaje = `La compra sigue en estado ${status} tras ${intento} consultas (~${intento * 5} s) ` +
    `(${ctx.order_name}, ${ctx.result_id}). Revisa el pedido en Shopify ANTES de reintentar: ` +
    'la etiqueta podría haberse comprado igualmente.';
}

return [{
  json: {
    ...ctx,
    status,
    intento,
    siguiente,
    mensaje,
    shippingLabels: resultado.shippingLabels ?? [],
  },
}];

// Un trabajo de impresión (Job) por cada documento comprado: primero las
// etiquetas (LABEL) y después los formularios de aduana (CUSTOMS_FORM).
// Cada item de salida es el Job que se publica tal cual en MQTT.
const d = $input.first().json;

const docs = [];
for (const label of d.shippingLabels ?? []) {
  for (const doc of label.shippingDocuments ?? []) {
    if (doc?.url) docs.push({ doc, label });
  }
}

const ORDEN = { LABEL: 0, CUSTOMS_FORM: 1 };
docs.sort((a, b) => (ORDEN[a.doc.documentType] ?? 9) - (ORDEN[b.doc.documentType] ?? 9));

if (docs.length === 0) {
  throw new Error(`Etiqueta comprada pero sin documentos imprimibles (${d.order_name}). Descárgala desde Shopify.`);
}

return docs.map(({ doc, label }, i) => {
  const esAduana = doc.documentType === 'CUSTOMS_FORM';
  const job = {
    id: `shopify-${d.order_id}-label-${i + 1}`,
    title: `Pedido ${d.order_name} · ${esAduana ? 'Aduana' : 'Etiqueta'}`,
    ...(d.printer ? { printer: d.printer } : {}),   // p. ej. otro alias para aduanas si van en A4
    copies: 1,
    format: String(doc.format ?? '').toUpperCase() === 'ZPL' ? 'zpl' : 'pdf',
    url: doc.url,
    meta: {
      order_id: d.order_id,
      order_name: d.order_name,
      document_type: doc.documentType,
      shipping_label_id: label.id,
      tracking_number: label.trackingInfo?.number ?? null,
      carrier: label.trackingInfo?.company ?? null,
      tracking_url: label.trackingInfo?.url ?? null,
    },
  };
  return { json: job };
});
